import json,subprocess,urllib.request,pathlib,time
p=pathlib.Path(__file__).resolve().parent
a=json.loads(pathlib.Path('/tmp/jury-session.private.json').read_text());project=json.loads(pathlib.Path('docs/qa/final-ui-jury-review-20261008/data-truth-spot-check.json').read_text())['project']['id']
t=time.perf_counter();r=json.load(urllib.request.urlopen(urllib.request.Request('http://127.0.0.1:4200/api/azure-deploy/governance/'+project,headers={'Authorization':'Bearer '+a['token']}),timeout=60));backendMs=(time.perf_counter()-t)*1000
