code="""const fs=require('fs'),{performance}=require('perf_hooks');const p=JSON.parse(fs.readFileSync(0,'utf8'));const {AzureDeployController}=require('./dist/azure-deploy/azure-deploy.module');const c=Object.create(AzureDeployController.prototype);(async()=>{const results=[];for(const [method,endpoint,args]of [['resolveArtifactDigest','agent /resolve-digest',{registry:p.registry,repository:p.repository,tag:p.tag}],['inspectArtifactLabels','agent /inspect-artifact',{registry:p.registry,repository:p.repository,digest:p.digest}]]){const t=performance.now();try{const r=await c[method](args);results.push({endpoint,durationMs:performance.now()-t,found:r.found??r.available,readOnly:true})}catch(e){results.push({endpoint,durationMs:performance.now()-t,errorName:e.name,readOnly:true})}}console.log(JSON.stringify(results))})().catch(()=>process.exit(1));"""
