v={'scope':'Existing production read-only registry/OCI resolver methods; no authorization/deploy/write method invoked','fullGovernanceMs':backendMs,'externalAgentCalls':json.loads(r),'note':'Separate sequential diagnostic sample; subtraction from a different full-request sample is not an exact exclusive backend time.'};(p/'external-read-timing.json').write_text(json.dumps(v,indent=2)+'\n');print(json.dumps(v))
